# Create output grid by applying transformation to non-background frames
def find_all_frames(grid):
    """Find all hollow rectangular frames with uniform border"""
    H, W = len(grid), len(grid[0])
    frames = []

    for r1 in range(H):
        for c1 in range(W):
            for h in range(3, H-r1+1):
                for w in range(3, W-c1+1):
                    r2, c2 = r1 + h - 1, c1 + w - 1

                    border_cells = [(r,c) for r in range(r1,r2+1) for c in range(c1,c2+1) 
                                   if r == r1 or r == r2 or c == c1 or c == c2]
                    interior_cells = [(r,c) for r in range(r1+1,r2) for c in range(c1+1,c2)]

                    if len(interior_cells) == 0:
                        continue

                    border_colors = [grid[r][c] for r,c in border_cells]
                    if len(set(border_colors)) != 1:
                        continue

                    b_color = border_colors[0]
                    interior_vals = set([grid[r][c] for r,c in interior_cells])

                    # Filter out background color (1) frames - these are just enclosures
                    if b_color == 1:
                        continue

                    if b_color in interior_vals:
                        continue

                    frames.append((r1, c1, h, w, b_color, set(interior_cells)))

    return frames

frames = find_all_frames(input_grid)
print(f"Found {len(frames)} non-background frames:\n")
for i, (r1, c1, h, w, b_color, interior) in enumerate(frames):
    print(f"{i}: r[{r1},{c1}]-{[r1+h-1,c1+w-1]} b={b_color}, interior cells: {interior}")

# Apply transformation
output_grid = [row[:] for row in input_grid]  # Deep copy

for r1, c1, h, w, b_color, interior in frames:
    for r, c in interior:
        output_grid[r][c] = 3

# Print output
print("\nOutput grid:")
for row in output_grid:
    print(" ".join(str(x) for x in row))

